        ["The same settings as the game's menu (Esc / F1), saved in {0}."] = ("As mesmas configurações do menu do jogo (Esc / F1), salvas em {0}.", "La misma configuración que el menú del juego (Esc / F1), guardada en {0}."),
        ["The setup package could not be downloaded"] = ("O pacote de instalação não pôde ser baixado", "No se pudo descargar el paquete de instalación"),
        ["the shaders are ready before you play"] = ("os shaders ficam prontos antes de jogar", "los shaders quedan listos antes de jugar"),
        ["The shortcuts open this launcher: it looks for updates in the GitHub releases before it starts the game."] = ("Os atalhos abrem este launcher: ele procura atualizações nas releases do GitHub antes de iniciar o jogo.", "Los accesos directos abren este launcher: busca actualizaciones en GitHub antes de iniciar el juego."),
        ["The update stopped"] = ("A atualização parou", "La actualización se detuvo"),
        ["The verification stopped"] = ("A verificação parou", "La verificación se detuvo"),
        ["This folder already has the game"] = ("Esta pasta já tem o jogo", "Esta carpeta ya tiene el juego"),
        ["This folder has no TotK Recomp install. Use \"Install to another folder\"."] = ("Esta pasta não tem uma instalação do TotK Recomp. Use \"Instalar em outra pasta\".", "Esta carpeta no tiene una instalación de TotK Recomp. Usa \"Instalar en otra carpeta\"."),
        ["This folder has TotK Recomp {0} and {1} is out. The update keeps the extracted game, your saves and your settings, and redoes only what changed."] =
            ("Esta pasta tem o TotK Recomp {0} e o {1} já saiu. A atualização mantém o jogo extraído, os seus saves e as suas configurações, e refaz só o que mudou.",
             "Esta carpeta tiene TotK Recomp {0} y ya salió la {1}. La actualización conserva el juego extraído, tus partidas y tu configuración, y rehace solo lo que cambió."),
        ["This PC has no TotK Recomp setup package and the releases of {0} did not answer.\n\nCheck the connection and try again, or download TotK-Setup-<version>-windows.zip from the releases page and unpack it into a \"setup\" folder next to this launcher ({1})."] =
            ("Este PC não tem um pacote de instalação do TotK Recomp e as releases de {0} não responderam.\n\nVerifique a conexão e tente de novo, ou baixe o TotK-Setup-<versão>-windows.zip da página de releases e descompacte-o numa pasta \"setup\" ao lado deste launcher ({1}).",
             "Esta PC no tiene un paquete de instalación de TotK Recomp y las versiones de {0} no respondieron.\n\nRevisa la conexión e inténtalo de nuevo, o descarga TotK-Setup-<versión>-windows.zip de la página de versiones y descomprímelo en una carpeta \"setup\" junto a este launcher ({1})."),
        ["TotK Recomp {0}. Continue resumes an interrupted install and checks what is already done; the game files are only needed if they have to be extracted again."] =
            ("TotK Recomp {0}. Continuar retoma uma instalação interrompida e confere o que já foi feito; os arquivos do jogo só são pedidos se precisarem ser extraídos de novo.",
             "TotK Recomp {0}. Continuar retoma una instalación interrumpida y comprueba lo que ya está hecho; los archivos del juego solo se piden si hay que extraerlos de nuevo."),
        ["totk.ini could not be written: {0}"] = ("Não foi possível gravar o totk.ini: {0}", "No se pudo escribir totk.ini: {0}"),
        ["Translating the game code to C"] = ("Traduzindo o código do jogo para C", "Traduciendo el código del juego a C"),
        ["Try again"] = ("Tentar de novo", "Reintentar"),
        ["Ultrahand Launcher {0} is installed. The game is not touched."] = ("O Ultrahand Launcher {0} está instalado. O jogo não é alterado.", "Ultrahand Launcher {0} está instalado. El juego no se modifica."),
        ["Ultrahand Launcher {0}, installed in {1}."] = ("Ultrahand Launcher {0}, instalado em {1}.", "Ultrahand Launcher {0}, instalado en {1}."),
        ["Ultrahand Launcher in the Start menu."] = ("O Ultrahand Launcher no Menu Iniciar.", "Ultrahand Launcher en el menú Inicio."),
        ["Ultrahand Launcher on the Desktop."] = ("O Ultrahand Launcher na Área de Trabalho.", "Ultrahand Launcher en el Escritorio."),
        ["unknown size"] = ("tamanho desconhecido", "tamaño desconocido"),
        ["Unpacking the setup package"] = ("Descompactando o pacote de instalação", "Descomprimiendo el paquete de instalación"),
        ["Up to date · {0} is the latest version"] = ("Atualizado · {0} é a versão mais recente", "Actualizado · {0} es la versión más reciente"),
        ["Update"] = ("Atualizar", "Actualizar"),
        ["Update available"] = ("Atualização disponível", "Actualización disponible"),
        ["Update available: {0}"] = ("Atualização disponível: {0}", "Actualización disponible: {0}"),
        ["Update launcher to {0}"] = ("Atualizar o launcher para {0}", "Actualizar el launcher a {0}"),
        ["Updated"] = ("Atualizado", "Actualizado"),
        ["Updates"] = ("Atualizações", "Actualizaciones"),
        ["Updating launcher… {0}%"] = ("Atualizando o launcher… {0}%", "Actualizando el launcher… {0}%"),
        ["Updating your game"] = ("Atualizando o seu jogo", "Actualizando tu juego"),
        ["Verified"] = ("Verificado", "Verificado"),
        ["Verify · {0}"] = ("Verificação · {0}", "Verificación · {0}"),
        ["Verify files"] = ("Verificar os arquivos", "Verificar archivos"),
        ["Verifying the files"] = ("Verificando os arquivos", "Verificando los archivos"),
        ["Version {0} is out. This copy is not the installed one, so it cannot update itself."] = ("A versão {0} saiu. Esta cópia não é a instalada, então não consegue se atualizar.", "Salió la versión {0}. Esta copia no es la instalada, así que no puede actualizarse."),
        ["Version {0} is out: use \"Update launcher\" at the top of the window."] = ("A versão {0} saiu: use \"Atualizar o launcher\" no topo da janela.", "Salió la versión {0}: usa \"Actualizar el launcher\" arriba en la ventana."),
        ["Wait for the current run to finish, then change the settings."] = ("Espere a execução atual terminar e depois mude as configurações.", "Espera a que termine la ejecución actual y luego cambia la configuración."),
        ["Wait for the current run to finish, then update the launcher."] = ("Espere a execução atual terminar e depois atualize o launcher.", "Espera a que termine la ejecución actual y luego actualiza el launcher."),
        ["What went wrong"] = ("O que deu errado", "Qué salió mal"),
        ["What's new in Ultrahand Launcher {0}"] = ("Novidades do Ultrahand Launcher {0}", "Novedades de Ultrahand Launcher {0}"),
        ["You can also drop the files on this window. NSZ and XCZ work as they are: the installer decompresses them."] = ("Você também pode soltar os arquivos nesta janela. NSZ e XCZ funcionam como estão: o instalador os descompacta.", "También puedes soltar los archivos en esta ventana. NSZ y XCZ funcionan tal cual: el instalador los descomprime."),
        ["you can keep using your PC"] = ("você pode continuar usando o PC", "puedes seguir usando tu PC"),
        ["You have {0}. The launcher looks for a new version each time it opens."] = ("Você tem a {0}. O launcher procura uma versão nova toda vez que abre.", "Tienes la {0}. El launcher busca una versión nueva cada vez que se abre."),
        ["Your game is ready"] = ("O seu jogo está pronto", "Tu juego está listo"),
        ["Your game was updated"] = ("O seu jogo foi atualizado", "Tu juego se actualizó"),
        ["Zips the save folder: your saves, the game's own backup copy of them, the account id and the play time. Close the game first: a backup made while the game is saving can catch a save half written."] =
            ("Compacta a pasta do save: os seus saves, a cópia de segurança que o próprio jogo faz deles, o ID da conta e o tempo de jogo. Feche o jogo antes: um backup feito enquanto o jogo salva pode pegar um save pela metade.",
             "Comprime la carpeta de partidas: tus partidas, la copia de seguridad que hace el propio juego, el ID de la cuenta y el tiempo de juego. Cierra el juego antes: una copia hecha mientras el juego guarda puede tomar una partida a medio escribir."),

        // ---- game settings: tabs, groups and names (pt-BR from the game's own menu)
        ["Screen"] = ("Tela", "Pantalla"),
        ["Game"] = ("Jogo", "Juego"),
        ["Sound"] = ("Som", "Sonido"),
        ["Controls"] = ("Controles", "Controles"),
        ["Menu"] = ("Menu", "Menú"),
        ["Picture"] = ("Imagem", "Imagen"),
        ["Colour"] = ("Cor", "Color"),
        ["Analog sticks"] = ("Analógicos", "Palancas analógicas"),
        ["Automatic"] = ("Automático", "Automático"),
        ["Automatic (from Windows)"] = ("Automático (do Windows)", "Automático (de Windows)"),
        ["Off"] = ("Desligado", "Desactivado"),
        ["Full"] = ("Completo", "Completo"),
        ["Light"] = ("Leve", "Leve"),
        ["Medium"] = ("Médio", "Medio"),
        ["Fullscreen"] = ("Tela cheia", "Pantalla completa"),
        ["Fills the screen with the game; F11 toggles it."] = ("O jogo ocupa a tela inteira; F11 alterna.", "El juego ocupa toda la pantalla; F11 lo alterna."),
        ["Window size"] = ("Tamanho da janela", "Tamaño de la ventana"),
        ["Size of the game window when not fullscreen."] = ("Tamanho da janela do jogo fora da tela cheia.", "Tamaño de la ventana del juego cuando no está en pantalla completa."),
        ["Presentation"] = ("Apresentação", "Presentación"),
        ["How finished frames reach the screen."] = ("Como os quadros prontos chegam à tela.", "Cómo llegan a la pantalla los cuadros terminados."),
        ["Immediate"] = ("Imediato", "Inmediato"),
        ["Performance overlay"] = ("Indicador de desempenho", "Indicador de rendimiento"),
        ["Frame rate in the top right corner. Full adds frame times with a graph, CPU, GPU and memory load, temperatures and the render thread's waits. F10 cycles the modes."] =
            ("Taxa de quadros no canto superior direito. Completo adiciona tempos de quadro com um gráfico, uso de CPU, GPU e memória, temperaturas e as esperas da thread de renderização. F10 alterna os modos.",
             "Cuadros por segundo en la esquina superior derecha. Completo agrega tiempos de cuadro con un gráfico, uso de CPU, GPU y memoria, temperaturas y las esperas del hilo de renderizado. F10 alterna los modos."),
        ["Game resolution"] = ("Resolução do jogo", "Resolución del juego"),
        ["The size the game draws its picture and interface in. Above 1920 x 1080 the game needs more video memory and GPU time. A wider size (21:9) widens the camera's view and moves the HUD to the screen's corners; a taller one (16:10, 3:2) moves it to the top and bottom edges."] =
            ("O tamanho em que o jogo desenha a imagem e a interface. Acima de 1920 x 1080 o jogo precisa de mais memória de vídeo e tempo de GPU. Um tamanho mais largo (21:9) amplia a visão da câmera e leva o HUD para os cantos da tela; um mais alto (16:10, 3:2) leva para as bordas de cima e de baixo.",
             "El tamaño en que el juego dibuja la imagen y la interfaz. Por encima de 1920 x 1080 el juego necesita más memoria de video y tiempo de GPU. Un tamaño más ancho (21:9) amplía la vista de la cámara y lleva el HUD a las esquinas; uno más alto (16:10, 3:2) lo lleva a los bordes de arriba y abajo."),
        ["3D render scale"] = ("Escala da renderização 3D", "Escala de renderizado 3D"),
        ["Size of the 3D scene relative to the game resolution; the game's FSR scales it to that size. Above 100 % smooths jagged edges (supersampling) at a high GPU cost."] =
            ("Tamanho da cena 3D em relação à resolução do jogo; o FSR do jogo a escala para esse tamanho. Acima de 100 % suaviza o serrilhado (supersampling) com alto custo de GPU.",
             "Tamaño de la escena 3D respecto de la resolución del juego; el FSR del juego la escala a ese tamaño. Por encima de 100 % suaviza los bordes dentados (supersampling) con un alto costo de GPU."),
        ["Game (83 %)"] = ("Jogo (83 %)", "Juego (83 %)"),
        ["Dynamic resolution"] = ("Resolução dinâmica", "Resolución dinámica"),
        ["Lets the game lower the 3D scene to 90 or 80 %. It judges by an estimate made for the Switch that ignores your GPU, so wide scenes drop even on a fast PC. Off keeps the render scale."] =
            ("Deixa o jogo baixar a cena 3D para 90 ou 80 %. Ele decide por uma estimativa feita para o Switch que ignora a sua GPU, então cenas largas caem mesmo num PC rápido. Desligado mantém a escala de renderização.",
             "Deja que el juego baje la escena 3D a 90 u 80 %. Decide con una estimación hecha para la Switch que ignora tu GPU, así que las escenas anchas bajan incluso en una PC rápida. Desactivado mantiene la escala de renderizado."),
        ["Shadow map size"] = ("Tamanho do mapa de sombras", "Tamaño del mapa de sombras"),
        ["Size of the sun's shadow map. The game's own size changes with the view, down to about 400 near the ground, so leaf shadows look blocky and jump; a fixed size keeps them still and sharper. Above 1024 the shadows cost more GPU time and video memory; 256 is for integrated GPUs short of memory bandwidth."] =
            ("Tamanho do mapa de sombras do sol. O tamanho do próprio jogo muda com a vista, chegando a uns 400 perto do chão, então as sombras das folhas ficam quadriculadas e pulam; um tamanho fixo as deixa paradas e mais nítidas. Acima de 1024 as sombras custam mais tempo de GPU e memória de vídeo; 256 é para GPUs integradas com pouca largura de banda.",
             "Tamaño del mapa de sombras del sol. El tamaño propio del juego cambia con la vista, hasta unos 400 cerca del suelo, así que las sombras de las hojas se ven pixeladas y saltan; un tamaño fijo las deja quietas y más nítidas. Por encima de 1024 las sombras cuestan más tiempo de GPU y memoria de video; 256 es para GPU integradas con poco ancho de banda."),
        ["Game (changes)"] = ("Do jogo (varia)", "Del juego (varía)"),
        ["Scaling to the window"] = ("Escala para a janela", "Escalado a la ventana"),
        ["How the picture is scaled when the window is larger than the game resolution. FSR keeps edges and detail sharper than bilinear."] =
            ("Como a imagem é escalada quando a janela é maior que a resolução do jogo. O FSR mantém bordas e detalhes mais nítidos que o bilinear.",
             "Cómo se escala la imagen cuando la ventana es más grande que la resolución del juego. FSR mantiene los bordes y detalles más nítidos que el bilineal."),
        ["FSR sharpness"] = ("Nitidez do FSR", "Nitidez de FSR"),
        ["Sharpening after FSR scaling; 0 turns it off."] = ("Nitidez aplicada depois da escala do FSR; 0 desliga.", "Nitidez aplicada después del escalado FSR; 0 la desactiva."),
        ["Picture shape"] = ("Formato da imagem", "Forma de la imagen"),
        ["When the window's shape differs from the game resolution's (a 16:9 picture on a 21:9 screen): keep the picture's shape with black bars, or stretch it over the window."] =
            ("Quando o formato da janela difere do da resolução do jogo (uma imagem 16:9 numa tela 21:9): manter o formato com barras pretas ou esticar a imagem na janela.",
             "Cuando la forma de la ventana difiere de la de la resolución del juego (una imagen 16:9 en una pantalla 21:9): mantener la forma con barras negras o estirarla sobre la ventana."),
        ["Black bars"] = ("Barras pretas", "Barras negras"),
        ["Stretch"] = ("Esticar", "Estirar"),
        ["Movie shape"] = ("Formato dos vídeos", "Forma de los videos"),
        ["When the game resolution is not 16:9, keep the cutscene movies' own shape with black bars, or stretch them over the whole picture. Applies from the next movie."] =
            ("Quando a resolução do jogo não é 16:9, manter o formato dos vídeos das cenas com barras pretas ou esticá-los na imagem inteira. Vale a partir do próximo vídeo.",
             "Cuando la resolución del juego no es 16:9, mantener la forma de los videos de las escenas con barras negras o estirarlos sobre toda la imagen. Se aplica desde el próximo video."),
        ["Field of view"] = ("Campo de visão", "Campo de visión"),
        ["How much of the world the camera shows, in percent of the game's own. Game version 1.4.3 only."] = ("Quanto do mundo a câmera mostra, em porcentagem do original do jogo. Só na versão 1.4.3 do jogo.", "Cuánto del mundo muestra la cámara, en porcentaje del original del juego. Solo en la versión 1.4.3 del juego."),
        ["Texture filtering"] = ("Filtragem de texturas", "Filtrado de texturas"),
        ["Anisotropic filtering of surface textures: ground, roads and walls seen at a shallow angle stay sharp into the distance instead of blurring. Game: the level the game asks for, as on the Switch."] =
            ("Filtragem anisotrópica das texturas de superfície: chão, estradas e paredes vistos em ângulo baixo ficam nítidos à distância em vez de borrados. Jogo: o nível que o jogo pede, como no Switch.",
             "Filtrado anisotrópico de las texturas de superficie: el suelo, los caminos y las paredes vistos en ángulo bajo se ven nítidos a la distancia en vez de borrosos. Juego: el nivel que pide el juego, como en la Switch."),
        ["Shadow resolution"] = ("Resolução das sombras", "Resolución de las sombras"),
        ["Draws the sun's shadow maps this many times larger on each side than the game's 960x960: sharper shadow edges and leaf shadows. Takes effect at the next start."] =
            ("Desenha os mapas de sombra do sol essa quantidade de vezes maior em cada lado que os 960x960 do jogo: bordas de sombra e sombras de folhas mais nítidas. Vale na próxima abertura.",
             "Dibuja los mapas de sombra del sol esa cantidad de veces más grande por lado que los 960x960 del juego: bordes de sombra y sombras de hojas más nítidos. Se aplica en el próximo inicio."),
        ["Shadow cascade range"] = ("Alcance das cascatas de sombra", "Alcance de las cascadas de sombra"),
        ["Moves the steps where shadows turn softer (the game's 20, 40, 80 and 160 m) further away. Spreads the shadow map over more ground: raise Shadow resolution with it. Takes effect at the next start."] =
            ("Afasta os degraus em que as sombras ficam mais suaves (os 20, 40, 80 e 160 m do jogo). Espalha o mapa de sombras por mais terreno: aumente a Resolução das sombras junto. Vale na próxima abertura.",
             "Aleja los escalones donde las sombras se suavizan (los 20, 40, 80 y 160 m del juego). Reparte el mapa de sombras sobre más terreno: sube la Resolución de las sombras junto con esto. Se aplica en el próximo inicio."),
        ["Soft shadows"] = ("Sombras suaves", "Sombras suaves"),
        ["Sun shadows sharp where an object meets the ground and softer the further the shadow falls (PCSS). 0 keeps the game's filter. Takes effect at the next start."] =
            ("Sombras do sol nítidas onde o objeto toca o chão e mais suaves quanto mais longe a sombra cai (PCSS). 0 mantém o filtro do jogo. Vale na próxima abertura.",
             "Sombras del sol nítidas donde el objeto toca el suelo y más suaves cuanto más lejos cae la sombra (PCSS). 0 mantiene el filtro del juego. Se aplica en el próximo inicio."),
        ["Contact shadows"] = ("Sombras de contato", "Sombras de contacto"),
        ["Small sun shadows the shadow maps miss: at feet, under stones, in grass and creases. Traced on the screen after lighting. Takes effect at the next start."] =
            ("Pequenas sombras do sol que os mapas de sombra perdem: nos pés, embaixo de pedras, na grama e em dobras. Traçadas na tela depois da iluminação. Vale na próxima abertura.",
             "Pequeñas sombras del sol que los mapas de sombra pierden: en los pies, bajo las piedras, en el pasto y en los pliegues. Se trazan en pantalla después de la iluminación. Se aplica en el próximo inicio."),
        ["NVIDIA DLSS for the 3D scene, on NVIDIA RTX GPUs with nvngx_dlss.dll next to totk.exe. Takes effect at the next start."] =
            ("NVIDIA DLSS para a cena 3D, em GPUs NVIDIA RTX com o nvngx_dlss.dll ao lado do totk.exe. Vale na próxima abertura.",
             "NVIDIA DLSS para la escena 3D, en GPU NVIDIA RTX con nvngx_dlss.dll junto a totk.exe. Se aplica en el próximo inicio."),
        ["DLSS mode"] = ("Modo do DLSS", "Modo de DLSS"),
        ["DLAA draws the 3D scene at full resolution. Quality, Balanced, Performance and Ultra Performance draw it at 67, 58, 50 and 33 % and let DLSS scale it up, which saves GPU time; they replace the 3D render scale."] =
            ("O DLAA desenha a cena 3D na resolução completa. Qualidade, Equilibrado, Desempenho e Ultra Desempenho a desenham em 67, 58, 50 e 33 % e deixam o DLSS ampliar, o que economiza tempo de GPU; eles substituem a escala da renderização 3D.",
             "DLAA dibuja la escena 3D a resolución completa. Calidad, Equilibrado, Rendimiento y Ultra Rendimiento la dibujan al 67, 58, 50 y 33 % y dejan que DLSS la escale, lo que ahorra tiempo de GPU; reemplazan la escala de renderizado 3D."),
        ["DLAA (native)"] = ("DLAA (nativo)", "DLAA (nativo)"),
        ["Quality"] = ("Qualidade", "Calidad"),
        ["Balanced"] = ("Equilibrado", "Equilibrado"),
        ["Performance"] = ("Desempenho", "Rendimiento"),
        ["Ultra Performance"] = ("Ultra Desempenho", "Ultra Rendimiento"),
        ["DLSS model"] = ("Modelo do DLSS", "Modelo de DLSS"),
        ["Which DLSS model runs. Automatic follows NVIDIA's advice per mode: K for DLAA, Quality and Balanced, M for Performance, L for Ultra Performance. J: slightly less ghosting behind moving characters, a little more flicker. K: the sharpest model in every mode."] =
            ("Qual modelo do DLSS roda. Automático segue a recomendação da NVIDIA por modo: K para DLAA, Qualidade e Equilibrado, M para Desempenho, L para Ultra Desempenho. J: um pouco menos de rastro atrás de personagens em movimento, um pouco mais de cintilação. K: o modelo mais nítido em todos os modos.",
             "Qué modelo de DLSS se usa. Automático sigue la recomendación de NVIDIA por modo: K para DLAA, Calidad y Equilibrado, M para Rendimiento, L para Ultra Rendimiento. J: un poco menos de estela detrás de los personajes en movimiento, un poco más de parpadeo. K: el modelo más nítido en todos los modos."),
        ["K (sharpest)"] = ("K (mais nítido)", "K (más nítido)"),
        ["J (less ghosting)"] = ("J (menos rastro)", "J (menos estela)"),
        ["DLSS character trails"] = ("Rastros de personagens no DLSS", "Estelas de personajes en DLSS"),
        ["Reduces the faint trails behind moving characters, animals and what they hold: DLSS takes less of the previous frames there. Stronger removes more of the trails and leaves those edges a little less smooth."] =
            ("Reduz os rastros fracos atrás de personagens, animais e do que eles seguram em movimento: o DLSS usa menos dos quadros anteriores ali. Mais forte remove mais rastros e deixa essas bordas um pouco menos suaves.",
             "Reduce las estelas tenues detrás de personajes, animales y lo que sostienen en movimiento: DLSS usa menos de los cuadros anteriores ahí. Más fuerte quita más estelas y deja esos bordes un poco menos suaves."),
        ["Game anti-aliasing (FXAA)"] = ("Antisserrilhado do jogo (FXAA)", "Antialiasing del juego (FXAA)"),
        ["The game's own FXAA edge smoothing. It blurs fine detail a little; with DLAA on it is not needed."] =
            ("A suavização de bordas FXAA do próprio jogo. Borra um pouco os detalhes finos; com o DLAA ligado não é necessária.",
             "El suavizado de bordes FXAA del propio juego. Desenfoca un poco los detalles finos; con DLAA activado no hace falta."),
        ["Colour profile"] = ("Perfil de cor", "Perfil de color"),
        ["Sets the four values below. Vivid: more contrast and saturation, shadows opened a little (made for OLED screens). Clarity: a little more contrast, saturation and brightness. Moving a value makes the profile Custom."] =
            ("Define os quatro valores abaixo. Vívido: mais contraste e saturação, sombras um pouco mais abertas (feito para telas OLED). Clareza: um pouco mais de contraste, saturação e brilho. Mexer em um valor muda o perfil para Personalizado.",
             "Define los cuatro valores de abajo. Vívido: más contraste y saturación, sombras un poco más abiertas (hecho para pantallas OLED). Claridad: un poco más de contraste, saturación y brillo. Mover un valor cambia el perfil a Personalizado."),
        ["Game's own"] = ("Do jogo", "Del juego"),
        ["Vivid (OLED)"] = ("Vívido (OLED)", "Vívido (OLED)"),
        ["Clarity"] = ("Clareza", "Claridad"),
        ["Custom"] = ("Personalizado", "Personalizado"),
        ["Brightness"] = ("Brilho", "Brillo"),
        ["Added to every colour; 0 leaves it."] = ("Somado a todas as cores; 0 não muda.", "Se suma a todos los colores; 0 no cambia nada."),
        ["Contrast"] = ("Contraste", "Contraste"),
        ["Spreads colours away from mid-grey (above 100 %) or towards it; 100 % leaves them."] = ("Afasta as cores do cinza médio (acima de 100 %) ou as aproxima dele; 100 % não muda.", "Aleja los colores del gris medio (por encima de 100 %) o los acerca; 100 % no cambia nada."),
        ["Saturation"] = ("Saturação", "Saturación"),
        ["Colour strength against grey; 100 % leaves it."] = ("Força da cor em relação ao cinza; 100 % não muda.", "Intensidad del color frente al gris; 100 % no cambia nada."),
        ["Gamma"] = ("Gama", "Gamma"),
        ["Below 1 brightens dark and middle tones, above 1 darkens them; 1 leaves them."] = ("Abaixo de 1 clareia os tons escuros e médios, acima de 1 escurece; 1 não muda.", "Por debajo de 1 aclara los tonos oscuros y medios, por encima de 1 los oscurece; 1 no cambia nada."),
        ["HDR output"] = ("Saída HDR", "Salida HDR"),
        ["Bright highlights on an HDR display. Needs HDR turned on in Windows (\"Use HDR\"); without it the picture stays SDR. Applies after a restart. The colour profile above is for SDR and is not used in HDR."] =
            ("Realces brilhantes numa tela HDR. Precisa do HDR ligado no Windows (\"Usar HDR\"); sem isso a imagem fica em SDR. Vale depois de reiniciar o jogo. O perfil de cor acima é para SDR e não é usado em HDR.",
             "Realces brillantes en una pantalla HDR. Necesita HDR activado en Windows (\"Usar HDR\"); sin eso la imagen queda en SDR. Se aplica después de reiniciar el juego. El perfil de color de arriba es para SDR y no se usa en HDR."),
        ["Peak brightness"] = ("Brilho máximo", "Brillo máximo"),
        ["Your display's peak in nits; the brightest highlights stop there."] = ("O pico da sua tela em nits; os realces mais fortes param aí.", "El pico de tu pantalla en nits; los realces más fuertes se detienen ahí."),
        ["Game brightness"] = ("Brilho do jogo", "Brillo del juego"),
        ["Nits of the picture's white (paper white). 203 is the HDR reference; raise it in a bright room."] = ("Nits do branco da imagem (paper white). 203 é a referência do HDR; aumente num ambiente claro.", "Nits del blanco de la imagen (paper white). 203 es la referencia de HDR; súbelo en una habitación iluminada."),
        ["HUD and menu brightness"] = ("Brilho do HUD e do menu", "Brillo del HUD y del menú"),
        ["Nits of the HUD's and the menu's white."] = ("Nits do branco do HUD e do menu.", "Nits del blanco del HUD y del menú."),
        ["Highlight hue correction"] = ("Correção de matiz dos realces", "Corrección de tono de los realces"),
        ["Bright colours such as fire and sparks turn towards white as in the game's own SDR picture, matching the light they cast; 0 keeps them fully saturated."] =
            ("Cores brilhantes como fogo e faíscas tendem ao branco como na imagem SDR do próprio jogo, combinando com a luz que emitem; 0 as mantém totalmente saturadas.",
             "Los colores brillantes como el fuego y las chispas tienden al blanco como en la imagen SDR del propio juego, igual que la luz que emiten; 0 los mantiene totalmente saturados."),
        ["Frame rate limit"] = ("Limite de quadros", "Límite de cuadros"),
        ["The most frames per second the game draws. Above 60 is experimental and needs the game speed to follow the clock (realtime = 1, the default)."] =
            ("O máximo de quadros por segundo que o jogo desenha. Acima de 60 é experimental e precisa que a velocidade do jogo siga o relógio (realtime = 1, o padrão).",
             "El máximo de cuadros por segundo que dibuja el juego. Por encima de 60 es experimental y necesita que la velocidad del juego siga el reloj (realtime = 1, el valor por defecto)."),
        ["Monitor rate"] = ("Taxa do monitor", "Frecuencia del monitor"),
        ["Frame queue"] = ("Fila de quadros", "Cola de cuadros"),
        ["The game starts a frame while the previous one waits for its turn on screen: far fewer dropped frames at the limit, up to one frame more input delay."] =
            ("O jogo começa um quadro enquanto o anterior espera a vez na tela: bem menos quadros perdidos no limite, com até um quadro a mais de atraso de comando.",
             "El juego empieza un cuadro mientras el anterior espera su turno en pantalla: muchos menos cuadros perdidos en el límite, con hasta un cuadro más de retraso de entrada."),
        ["Game language"] = ("Idioma do jogo", "Idioma del juego"),
        ["Language of the game's text and voices."] = ("Idioma dos textos e das vozes do jogo.", "Idioma de los textos y las voces del juego."),
        ["Console mode"] = ("Modo do console", "Modo de la consola"),
        ["Whether the game thinks it runs docked or handheld."] = ("Se o jogo acha que está no modo TV ou no portátil.", "Si el juego cree que está en modo TV o portátil."),
        ["Docked"] = ("Modo TV", "Modo TV"),
        ["Handheld"] = ("Modo portátil", "Modo portátil"),
        ["Keep running out of focus"] = ("Continuar rodando fora de foco", "Seguir ejecutándose sin foco"),
        ["On (the default), the game keeps running while you are in another window, and the keyboard stays quiet until the window is in front again. Off, it pauses when its window loses focus, as on the Switch when Home is pressed; a load interrupted that way can stop for good."] =
            ("Ligado (o padrão), o jogo continua rodando enquanto você está em outra janela, e o teclado fica inativo até a janela voltar para a frente. Desligado, ele pausa quando a janela perde o foco, como no Switch ao apertar Home; um carregamento interrompido assim pode travar de vez.",
             "Activado (por defecto), el juego sigue ejecutándose mientras estás en otra ventana, y el teclado queda inactivo hasta que la ventana vuelva al frente. Desactivado, se pausa cuando la ventana pierde el foco, como en la Switch al presionar Home; una carga interrumpida así puede quedarse trabada."),
        ["Volume"] = ("Volume", "Volumen"),
        ["Master volume of the game."] = ("Volume geral do jogo.", "Volumen general del juego."),
        ["Speakers"] = ("Alto-falantes", "Altavoces"),
        ["Stereo or 5.1 surround output. Automatic picks 5.1 when the Windows speaker setup has six or more channels. Applies after a restart."] =
            ("Saída estéreo ou surround 5.1. Automático escolhe 5.1 quando a configuração de alto-falantes do Windows tem seis canais ou mais. Vale depois de reiniciar o jogo.",
             "Salida estéreo o envolvente 5.1. Automático elige 5.1 cuando la configuración de altavoces de Windows tiene seis canales o más. Se aplica después de reiniciar el juego."),
        ["Stereo"] = ("Estéreo", "Estéreo"),
        ["5.1 surround"] = ("Surround 5.1", "Envolvente 5.1"),
        ["Button layout"] = ("Layout dos botões", "Distribución de botones"),
        ["Which button is A. Nintendo: the right one, as on a Switch. Xbox: the bottom one, as labelled on an Xbox controller (cross on a PlayStation controller). Automatic picks Nintendo for controllers with Nintendo labels and Xbox for the others."] =
            ("Qual botão é o A. Nintendo: o da direita, como no Switch. Xbox: o de baixo, como marcado num controle de Xbox (o X num controle de PlayStation). Automático escolhe Nintendo para controles com marcação Nintendo e Xbox para os outros.",
             "Qué botón es A. Nintendo: el de la derecha, como en la Switch. Xbox: el de abajo, como está marcado en un control de Xbox (la X en un control de PlayStation). Automático elige Nintendo para controles con marcas de Nintendo y Xbox para los demás."),
        ["Nintendo (A right)"] = ("Nintendo (A à direita)", "Nintendo (A a la derecha)"),
        ["Xbox (A bottom)"] = ("Xbox (A embaixo)", "Xbox (A abajo)"),
        ["Button prompts"] = ("Ícones de botões", "Íconos de botones"),
        ["Which controller's buttons the game's prompts show. Nintendo: the game's own. Xbox: LB, RB, LT, RT, Menu, View and a d-pad cross. PC: the keys and mouse buttons of the keyboard's default layout. The game reads its prompts at start, so they change after a restart."] =
            ("De qual controle são os botões que os avisos do jogo mostram. Nintendo: os do próprio jogo. Xbox: LB, RB, LT, RT, Menu, View e uma cruz de direcional. PC: as teclas e os botões do mouse do layout padrão do teclado. O jogo lê os ícones ao abrir, então eles mudam depois de reiniciar.",
             "De qué control son los botones que muestran los avisos del juego. Nintendo: los del propio juego. Xbox: LB, RB, LT, RT, Menu, View y una cruceta. PC: las teclas y los botones del mouse de la distribución predeterminada del teclado. El juego lee los íconos al iniciar, así que cambian después de reiniciar."),
        ["Motion controls"] = ("Controles de movimento", "Controles de movimiento"),
        ["Aiming with the controller's gyroscope."] = ("Mirar com o giroscópio do controle.", "Apuntar con el giroscopio del control."),
        ["Vibration strength"] = ("Intensidade da vibração", "Intensidad de la vibración"),
        ["How strong the controller vibrates."] = ("O quanto o controle vibra.", "Qué tan fuerte vibra el control."),
        ["Vibration curve"] = ("Curva da vibração", "Curva de la vibración"),
        ["Lower values make weak vibration stronger."] = ("Valores menores deixam a vibração fraca mais forte.", "Valores más bajos hacen más fuerte la vibración débil."),
        ["Trigger vibration (Xbox)"] = ("Vibração dos gatilhos (Xbox)", "Vibración de los gatillos (Xbox)"),
        ["Vibrates the triggers of an Xbox controller too."] = ("Vibra também os gatilhos de um controle de Xbox.", "También hace vibrar los gatillos de un control de Xbox."),
        ["Mouse camera"] = ("Câmera com o mouse", "Cámara con el mouse"),
        ["Direct: the camera turns by how far the mouse moves, as in a PC game, with no stick dead zone or curve (games 1.4.3 and 1.2.1; 1.1.0 uses stick emulation). Stick emulation: the mouse acts as the right stick."] =
            ("Direta: a câmera gira conforme o mouse se move, como num jogo de PC, sem zona morta nem curva de analógico (jogo 1.4.3 e 1.2.1; o 1.1.0 usa a emulação do analógico). Emulação do analógico: o mouse age como o analógico direito.",
             "Directa: la cámara gira según cuánto se mueve el mouse, como en un juego de PC, sin zona muerta ni curva de palanca (juego 1.4.3 y 1.2.1; el 1.1.0 usa la emulación de palanca). Emulación de palanca: el mouse actúa como la palanca derecha."),
        ["Stick emulation"] = ("Emulação do analógico", "Emulación de palanca"),
        ["Direct"] = ("Direta", "Directa"),
        ["Mouse camera sensitivity"] = ("Sensibilidade da câmera no mouse", "Sensibilidad de la cámara con el mouse"),
        ["How fast the mouse turns the camera."] = ("A velocidade com que o mouse gira a câmera.", "Qué tan rápido gira la cámara con el mouse."),
        ["Mouse in the game's menus"] = ("Mouse nos menus do jogo", "Mouse en los menús del juego"),
        ["In the game's own menus (title, inventory, shops, dialogue choices) the pointer shows: the item under it is selected, left click confirms, right click goes back (game 1.4.3)."] =
            ("Nos menus do próprio jogo (título, inventário, lojas, escolhas de diálogo) o ponteiro aparece: o item embaixo dele fica selecionado, o clique esquerdo confirma e o direito volta (jogo 1.4.3).",
             "En los menús del propio juego (título, inventario, tiendas, opciones de diálogo) aparece el puntero: el elemento debajo queda seleccionado, el clic izquierdo confirma y el derecho vuelve (juego 1.4.3)."),
        ["Walk key"] = ("Tecla de andar", "Tecla de caminar"),
        ["While this key is held the keyboard's sticks shrink to the walk scale, so the keyboard can walk instead of run."] =
            ("Enquanto essa tecla está apertada, os analógicos do teclado diminuem para a intensidade do andar, para o teclado poder andar em vez de correr.",
             "Mientras mantienes esta tecla, las palancas del teclado se reducen a la escala de caminar, para que el teclado pueda caminar en vez de correr."),
        ["Caps Lock"] = ("Caps Lock", "Bloq Mayús"),
        ["Walk scale"] = ("Intensidade do andar", "Escala de caminar"),
        ["The tilt the keyboard's sticks get while the walk key is held. Half is a walk, the full tilt a run."] =
            ("A inclinação que os analógicos do teclado recebem com a tecla de andar apertada. Metade é andar, a inclinação toda é correr.",
             "La inclinación que reciben las palancas del teclado mientras se mantiene la tecla de caminar. La mitad es caminar, la inclinación completa es correr."),
        ["Left stick dead zone"] = ("Zona morta do analógico esquerdo", "Zona muerta de la palanca izquierda"),
        ["Right stick dead zone"] = ("Zona morta do analógico direito", "Zona muerta de la palanca derecha"),
        ["How far a gamepad stick moves before the game sees it. Raise it if the character or the camera moves on its own."] =
            ("O quanto o analógico do controle se move antes de o jogo perceber. Aumente se o personagem ou a câmera se mexerem sozinhos.",
             "Cuánto se mueve la palanca del control antes de que el juego lo note. Súbela si el personaje o la cámara se mueven solos."),
        ["Stick camera speed"] = ("Velocidade da câmera (analógico)", "Velocidad de la cámara (palanca)"),
        ["Multiplies the game's own right-stick camera speed, top speed included, at each of the game's five camera sensitivities. The mouse keeps its own setting."] =
            ("Multiplica a velocidade da câmera do analógico direito do próprio jogo, inclusive a máxima, em cada uma das cinco sensibilidades de câmera do jogo. O mouse mantém a própria configuração.",
             "Multiplica la velocidad de la cámara de la palanca derecha del propio juego, incluida la máxima, en cada una de las cinco sensibilidades de cámara del juego. El mouse mantiene su propia configuración."),
        ["Menu language"] = ("Idioma do menu", "Idioma del menú"),
        ["Language of the game's settings menu and the overlay."] = ("Idioma do menu de configurações do jogo e do indicador.", "Idioma del menú de configuración del juego y del indicador."),
        ["Shows \"Playing TotK Recomp\" with the play time in your Discord status while the game runs."] =
            ("Mostra \"Jogando TotK Recomp\" com o tempo de jogo no seu status do Discord enquanto o jogo roda.",
             "Muestra \"Jugando TotK Recomp\" con el tiempo de juego en tu estado de Discord mientras el juego se ejecuta."),

        // ---- game languages (installer/ini.py)
        ["Japanese"] = ("Japonês", "Japonés"),
